"""Recursive-descent parser for MiniDB's SQL subset.

Consumes the token list produced by ``minidb.tokenizer.tokenize`` (which
always ends with an EOF token) and builds the frozen AST nodes defined in
``minidb.types``. The statement and WHERE-expression grammars are
documented in the ``minidb.types`` module docstring:

* Precedence NOT > AND > OR; AND/OR are left-associative.
* Comparisons do not chain (``a = b = c`` is an error).
* ``IS [NOT] NULL`` produces ``IsNull(operand, negated)``.
* INSERT values must be literals, converted to Values: INTEGER token ->
  ``int``, STRING -> ``str``, TRUE/FALSE -> ``bool``, NULL -> ``None``.
* Column types in CREATE TABLE are the keywords INTEGER, TEXT, BOOLEAN,
  mapped to ``ColumnType``.

Any malformed input raises ``SQLSyntaxError``.
"""

from __future__ import annotations

from minidb.types import (
    COMPARISON_OPS,
    And,
    ColumnDef,
    ColumnRef,
    ColumnType,
    Comparison,
    CreateTableStmt,
    DeleteStmt,
    DropTableStmt,
    Expr,
    InsertStmt,
    IsNull,
    Literal,
    Not,
    Or,
    SelectStmt,
    SQLSyntaxError,
    Statement,
    Token,
    TokenType,
    Value,
)

__all__ = ["parse", "parse_script", "parse_expression"]


def parse(tokens: list[Token]) -> Statement:
    """Parse exactly one statement, optionally followed by a single ';',
    then EOF.

    Raises:
        SQLSyntaxError: if the tokens are not exactly one valid statement
            (including empty input, a lone ';', or trailing tokens).
    """
    if not tokens:
        raise SQLSyntaxError("Unexpected EOF")

    pos = 0
    def next_token():
        nonlocal pos
        if pos >= len(tokens):
            raise SQLSyntaxError("Unexpected EOF")
        token = tokens[pos]
        pos += 1
        return token

    def peek_token():
        if pos >= len(tokens):
            raise SQLSyntaxError("Unexpected EOF")
        return tokens[pos]

    def consume(token_type: TokenType):
        token = next_token()
        if token.type != token_type:
            raise SQLSyntaxError(f"Expected {token_type}, got {token.type}")
        return token.value

    def parse_create_table():
        consume(TokenType.KEYWORD)
        table_name = consume(TokenType.IDENTIFIER)
        consume(TokenType.OPERATOR)
        columns = []
        while peek_token().type != TokenType.OPERATOR or peek_token().value != ")":
            col_name = consume(TokenType.IDENTIFIER)
            col_type = consume(TokenType.KEYWORD)
            if col_type == "INTEGER":
                columns.append(ColumnDef(col_name, ColumnType.INTEGER))
            elif col_type == "TEXT":
                columns.append(ColumnDef(col_name, ColumnType.TEXT))
            elif col_type == "BOOLEAN":
                columns.append(ColumnDef(col_name, ColumnType.BOOLEAN))
            else:
                raise SQLSyntaxError(f"Unknown column type: {col_type}")
            if peek_token().type == TokenType.OPERATOR and peek_token().value == ",":
                consume(TokenType.OPERATOR)
        consume(TokenType.OPERATOR)
        return CreateTableStmt(table_name, tuple(columns))

    def parse_drop_table():
        consume(TokenType.KEYWORD)
        table_name = consume(TokenType.IDENTIFIER)
        return DropTableStmt(table_name)

    def parse_insert_stmt():
        consume(TokenType.KEYWORD)
        table_name = consume(TokenType.IDENTIFIER)
        columns = None
        if peek_token().type == TokenType.OPERATOR and peek_token().value == "(":
            consume(TokenType.OPERATOR)
            columns = []
            while peek_token().type != TokenType.OPERATOR or peek_token().value != ")":
                columns.append(consume(TokenType.IDENTIFIER))
                if peek_token().type == TokenType.OPERATOR and peek_token().value == ",":
                    consume(TokenType.OPERATOR)
            consume(TokenType.OPERATOR)
        consume(TokenType.KEYWORD)
        consume(TokenType.OPERATOR)
        values = []
        while peek_token().type != TokenType.OPERATOR or peek_token().value != ")":
            token = next_token()
            if token.type == TokenType.INTEGER:
                values.append(int(token.value))
            elif token.type == TokenType.STRING:
                values.append(token.value)
            elif token.type == TokenType.KEYWORD:
                if token.value == "TRUE":
                    values.append(True)
                elif token.value == "FALSE":
                    values.append(False)
                elif token.value == "NULL":
                    values.append(None)
                else:
                    raise SQLSyntaxError(f"Unexpected keyword: {token.value}")
            else:
                raise SQLSyntaxError(f"Unexpected token type: {token.type}")
            if peek_token().type == TokenType.OPERATOR and peek_token().value == ",":
                consume(TokenType.OPERATOR)
        consume(TokenType.OPERATOR)
        return InsertStmt(table_name, tuple(columns) if columns else None, tuple(values))

    def parse_select_stmt():
        consume(TokenType.KEYWORD)
        columns = None
        if peek_token().type == TokenType.OPERATOR and peek_token().value == "*":
            consume(TokenType.OPERATOR)
        else:
            columns = []
            while peek_token().type != TokenType.KEYWORD or peek_token().value != "FROM":
                columns.append(consume(TokenType.IDENTIFIER))
                if peek_token().type == TokenType.OPERATOR and peek_token().value == ",":
                    consume(TokenType.OPERATOR)
        consume(TokenType.KEYWORD)
        table_name = consume(TokenType.IDENTIFIER)
        where_expr = None
        if peek_token().type == TokenType.KEYWORD and peek_token().value == "WHERE":
            consume(TokenType.KEYWORD)
            where_expr = parse_expression(tokens[pos:])
            pos = len(tokens)
        return SelectStmt(table_name, tuple(columns) if columns else None, where_expr)

    def parse_delete_stmt():
        consume(TokenType.KEYWORD)
        table_name = consume(TokenType.IDENTIFIER)
        where_expr = None
        if peek_token().type == TokenType.KEYWORD and peek_token().value == "WHERE":
            consume(TokenType.KEYWORD)
            where_expr = parse_expression(tokens[pos:])
            pos = len(tokens)
        return DeleteStmt(table_name, where_expr)

    def parse_statement():
        token = peek_token()
        if token.type == TokenType.KEYWORD:
            if token.value == "CREATE":
                return parse_create_table()
            elif token.value == "DROP":
                return parse_drop_table()
            elif token.value == "INSERT":
                return parse_insert_stmt()
            elif token.value == "SELECT":
                return parse_select_stmt()
            elif token.value == "DELETE":
                return parse_delete_stmt()
        raise SQLSyntaxError(f"Unexpected keyword: {token.value}")

    stmt = parse_statement()
    if peek_token().type == TokenType.OPERATOR and peek_token().value == ";":
        consume(TokenType.OPERATOR)
    if peek_token().type != TokenType.EOF:
        raise SQLSyntaxError("Trailing tokens after statement")
    return stmt


def parse_script(tokens: list[Token]) -> list[Statement]:
    """Parse zero or more ';'-separated statements up to EOF.

    Empty statements (consecutive ';' or a trailing ';') are skipped; an
    empty token stream (just EOF) yields ``[]``.

    Raises:
        SQLSyntaxError: if any statement is malformed.
    """
    pos = 0
    statements = []
    def next_token():
        nonlocal pos
        if pos >= len(tokens):
            raise SQLSyntaxError("Unexpected EOF")
        token = tokens[pos]
        pos += 1
        return token

    def peek_token():
        if pos >= len(tokens):
            raise SQLSyntaxError("Unexpected EOF")
        return tokens[pos]

    def consume(token_type: TokenType):
        token = next_token()
        if token.type != token_type:
            raise SQLSyntaxError(f"Expected {token_type}, got {token.type}")
        return token.value

    while peek_token().type != TokenType.EOF:
        try:
            stmt = parse(tokens[pos:])
            pos += len(tokens) - 1
            if isinstance(stmt, (CreateTableStmt, DropTableStmt, InsertStmt, SelectStmt, DeleteStmt)):
                statements.append(stmt)
        except SQLSyntaxError:
            raise SQLSyntaxError("Malformed statement in script")
        if peek_token().type == TokenType.OPERATOR and peek_token().value == ";":
            consume(TokenType.OPERATOR)
    return statements


def parse_expression(tokens: list[Token]) -> Expr:
    """Parse a single WHERE-style expression that must consume every token
    up to EOF.

    Raises:
        SQLSyntaxError: if the tokens do not form exactly one expression.
    """
    pos = 0
    def next_token():
        nonlocal pos
        if pos >= len(tokens):
            raise SQLSyntaxError("Unexpected EOF")
        token = tokens[pos]
        pos += 1
        return token

    def peek_token():
        if pos >= len(tokens):
            raise SQLSyntaxError("Unexpected EOF")
        return tokens[pos]

    def consume(token_type: TokenType):
        token = next_token()
        if token.type != token_type:
            raise SQLSyntaxError(f"Expected {token_type}, got {token.type}")
        return token.value

    def parse_primary() -> Expr:
        token = peek_token()
        if token.type == TokenType.INTEGER:
            return Literal(int(consume(TokenType.INTEGER)))
        elif token.type == TokenType.STRING:
            return Literal(consume(TokenType.STRING))
        elif token.type == TokenType.KEYWORD:
            if token.value == "TRUE":
                return Literal(True)
            elif token.value == "FALSE":
                return Literal(False)
            elif token.value == "NULL":
                return Literal(None)
            else:
                raise SQLSyntaxError(f"Unexpected keyword: {token.value}")
        elif token.type == TokenType.IDENTIFIER:
            return ColumnRef(consume(TokenType.IDENTIFIER))
        elif token.type == TokenType.OPERATOR and token.value == "(":
            consume(TokenType.OPERATOR)
            expr = parse_expression(tokens[pos:])
            pos = len(tokens) - 1
            consume(TokenType.OPERATOR)
            return expr
        else:
            raise SQLSyntaxError(f"Unexpected token type: {token.type}")

    def parse_predicate() -> Expr:
        left = parse_primary()
        token = peek_token()
        if token.type == TokenType.OPERATOR and token.value in COMPARISON_OPS:
            op = consume(TokenType.OPERATOR)
            right = parse_primary()
            return Comparison(op, left, right)
        elif token.type == TokenType.KEYWORD and token.value == "IS":
            consume(TokenType.KEYWORD)
            token = next_token()
            if token.type == TokenType.KEYWORD and token.value == "NOT":
                consume(TokenType.KEYWORD)
                consume(TokenType.KEYWORD)
                return IsNull(left, True)
            elif token.type == TokenType.KEYWORD and token.value == "NULL":
                consume(TokenType.KEYWORD)
                return IsNull(left, False)
            else:
                raise SQLSyntaxError(f"Unexpected token: {token}")
        else:
            return left

    def parse_not_expr() -> Expr:
        token = peek_token()
        if token.type == TokenType.KEYWORD and token.value == "NOT":
            consume(TokenType.KEYWORD)
            operand = parse_not_expr()
            return Not(operand)
        else:
            return parse_predicate()

    def parse_and_expr() -> Expr:
        left = parse_not_expr()
        while peek_token().type == TokenType.KEYWORD and peek_token().value == "AND":
            consume(TokenType.KEYWORD)
            right = parse_not_expr()
            left = And(left, right)
        return left

    def parse_or_expr() -> Expr:
        left = parse_and_expr()
        while peek_token().type == TokenType.KEYWORD and peek_token().value == "OR":
            consume(TokenType.KEYWORD)
            right = parse_and_expr()
            left = Or(left, right)
        return left

    expr = parse_or_expr()
    if peek_token().type != TokenType.EOF:
        raise SQLSyntaxError("Trailing tokens after expression")
    return expr

